import React, { useState } from 'react';
import './style.css';

type Data = { label: string; value: number; min: number; max: number };

export default function ValueSlider({ data, onChange, readOnly }: {
  data: Data; onChange?: (next: Data) => void; readOnly: boolean;
}) {
  // 阅读时只改本地状态；编辑时通过 onChange 交回新数据
  const [value, setValue] = useState(data.value);
  return (
    <label className="vs">
      {data.label}：{value}
      <input type="range" min={data.min} max={data.max} value={value}
        onChange={(e) => {
          const next = Number(e.target.value);
          setValue(next);
          if (!readOnly) onChange?.({ ...data, value: next });
        }} />
    </label>
  );
}

// 可选：manifest.reader = "readData" 时，Agent 能读到派生值
export function readData(data: Data) {
  return { share: (data.value - data.min) / (data.max - data.min), derived: true };
}

